import sys
from typing import List, Tuple

def f(N: int, M: int, triples: List[Tuple[int, int, int]], Q: int, pairs: List[Tuple[int, int]]) -> int:
    # Sort the triples by b_i in descending order and then by c_i difference in descending order
    triples.sort(key=lambda x: (x[1] * 100 + x[2], x[2]))

    def query(ind: int, num: int) -> int:
        lo, hi = -1, len(triples)
        while hi - lo > 1:
            mid = (lo + hi) // 2
            if triples[mid][1] == num:
                return mid
            elif triples[mid][1] < num:
                lo = mid
            else:
                hi = mid
        if hi < len(triples) and triples[hi][1] == num:
            return hi
        else:
