        count = {}
        for x in arr:
            count[x] = count.get(x, 0) + 1
        max_count = 0
        for x in count:
            if count[x] > max_count:
                max_count = count[x]
        for x in count:
            if count[x] == max_count:
                return x
        return -1

    arr = [0] * (N + 1)
    for i in range(Q):
        num, cnt = pairs[i]
        arr[num] += cnt

    max_count = 0
    for x in arr:
        if x > max_count:
            max_count = x

    majorities = []
    for i in range(1, N + 1):
        if arr[i] == max_count:
            majorities.append(i)

    for num in majorities:
        ind = query(num, num)
        while ind!= -1:
            a, b, c = triples[ind]
            if c == 1:
                arr[b] -= 1
            ind = query(num, num)

    majorities = []
    for i in range(1, N + 1):
        if arr[i] == max_count:
            majorities.append(i)

    ans = 0
    for num in majorities:
        ind = query(num, num)
        while ind!= -1:
            a, b, c = triples[ind]
            if c == 2:
                ans += 1
            elif c == 3:
                ans += 2
            ind = query(num, num)

    return ans

